SELF = ("6.11/selfCheck: formula fingerprint matches the frozen stage-A packet; claims and identity were hidden during the formula pass and the hash-pinned formula-pass record was not edited after release; "
        "no ingredient, family count or position window assigned a band (the W-line only gated payload_lipid legs); W-line derived from the frozen list per W-LINE with every skipped candidate recorded; "
        "depositionLoad, persistence and resetCapacity present with rationales; counterevidence and whyNotNeighborBand specific (W2 where it applies); confidence names its limiting factor; "
        "N-ALT neighbors consistent with confidences; projection fields derived mechanically (T1, T6, T4, W-LIVE, I1, I3, D1-D3, 13.7, 13.8); no catalog, web or other-lane input.")


def P(value, conf, neigh, rationale, rules, **kw):
    d = {"value": value, "confidence": conf, "neighboringAlternative": neigh, "rationale": rationale, "ruleIds": rules}
    d.update(kw)
    return d


def ND(rationale="Not supported: none of Piroctone Olamine, Climbazole, Selenium Sulfide or Selenium Disulfide in the complete INCI (formula-only; unchanged by the reveal)."):
    return P("not_supported", "high", "none", rationale, ["11", "DS1"])


NODOT = {"value": False, "confidence": "n/a", "evidence": "No D1 stem (tiefenrein, deep clean, clarifying shampoo, detox-reinigung) in the product name or any manufacturer/pack claim; no directions limiting use to occasional resets."}


def d2no(conf, why="D1 false -> not_flagged (D2)."):
    return {"value": "not_flagged", "confidence": conf, "rationale": why}


